import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    for _ in range(T):
        try:
            n_str = next(iterator)
            N = int(n_str)
            strings = []
            for _ in range(N):
                strings.append(next(iterator))

            result = []
            for i in range(N):
                # We pick the character opposite to the i-th character of the i-th string
                if strings[i][i] == '0':
                    result.append('1')
                else:
                    result.append('0')

            print("".join(result))

        except StopIteration:
            break

if __name__ == "__main__":
    solve()
